.bs-btn,
button[type="submit"]:not(.bs-search-form__submit),
input[type="submit"],
.wp-block-button__link,
.wp-element-button{display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: .5em;
	padding: .75em 1.5em;
	background: var(--bs-primary);
	color: #fff;
	font-family: inherit;
	font-size: 1em;
	font-weight: var(--bs-btn-weight);
	line-height: 1.2;
	text-transform: var(--bs-btn-transform);
	text-decoration: none;
	border: 2px solid transparent;
	border-radius: var(--bs-btn-radius);
	cursor: pointer;
	transition: background-color .2s ease, color .2s ease, border-color .2s ease, transform .2s ease, box-shadow .2s ease;}
.bs-btn:hover,
button[type="submit"]:not(.bs-search-form__submit):hover,
input[type="submit"]:hover,
.wp-block-button__link:hover,
.wp-element-button:hover{background: color-mix(in srgb, var(--bs-primary) 85%, #000);
	color: #fff;}
.bs-btn--sm{padding: .55em 1.1em;
	font-size: .92em;}
.bs-btn--lg{padding: 1em 2em;
	font-size: 1.1em;}
.bs-btn--secondary{background: var(--bs-secondary);}
.bs-btn--secondary:hover{background: color-mix(in srgb, var(--bs-secondary) 85%, #000);}
.bs-btn--outline,
.is-style-outline > .wp-block-button__link{background: transparent;
	color: var(--bs-primary);
	border-color: currentColor;}
.bs-btn--outline:hover,
.is-style-outline > .wp-block-button__link:hover{background: var(--bs-primary);
	color: #fff;
	border-color: var(--bs-primary);}
.bs-btn--white{background: #fff;
	color: var(--bs-heading);}
.bs-btn--white:hover{background: var(--bs-light);
	color: var(--bs-primary);}
.bs-btn--link{padding-left: 0;
	padding-right: 0;
	background: none;
	color: var(--bs-link);}
.bs-btn--link:hover{background: none;
	color: var(--bs-link-hover);}
[hidden]{display: none !important;}
@media (min-width: 850px){.bs-hide-desktop{display: none !important;}}
@media (min-width: 550px) and (max-width: 849px){.bs-hide-tablet{display: none !important;}}
@media (max-width: 549px){.bs-hide-mobile{display: none !important;}}

.bs-animations .bs-animate{opacity: 0;
	transition: opacity calc(var(--bs-duration, 700ms) * var(--bs-motion-speed, 1)) ease, transform calc(var(--bs-duration, 700ms) * var(--bs-motion-speed, 1)) var(--bs-motion-ease, cubic-bezier(.2, .7, .2, 1)), filter calc(var(--bs-duration, 700ms) * var(--bs-motion-speed, 1)) ease;
	transition-delay: var(--bs-delay, 0ms);
	will-change: opacity, transform;}
.bs-animations .bs-animate--fade-up{transform: translateY(40px);}
.bs-animations .bs-animate--fade-down{transform: translateY(-40px);}
.bs-animations .bs-animate--fade-left{transform: translateX(40px);}
.bs-animations .bs-animate--fade-right{transform: translateX(-40px);}
.bs-animations .bs-animate--zoom-in{transform: scale(.88);}
.bs-animations .bs-animate--zoom-out{transform: scale(1.12);}
.bs-animations .bs-animate--flip-up{transform: perspective(800px) rotateX(25deg); transform-origin: bottom;}
.bs-animations .bs-animate--blur-in{filter: blur(8px); transform: translateY(12px) scale(.98);}
.bs-animations .bs-animate--rotate-in{transform: rotate(-7deg) scale(.96);}
.bs-animations .bs-animate--bounce-in{transform: translateY(22px) scale(.88); transition-timing-function: cubic-bezier(.2, .8, .25, 1.18);}

@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover{transition: transform .24s cubic-bezier(.2, .7, .2, 1), box-shadow .24s ease, filter .24s ease;}}
@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover--lift:hover,
	.bs-hover--lift:focus-within{transform: translateY(-4px); box-shadow: 0 12px 28px rgba(28, 38, 53, .14);}}
@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover--zoom:hover,
	.bs-hover--zoom:focus-within{transform: scale(1.025);}}
@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover--glow:hover,
	.bs-hover--glow:focus-within{transform: translateY(-2px); filter: drop-shadow(0 7px 14px rgba(28, 38, 53, .2));}}
@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover--grayscale{filter: grayscale(1);}}
@media (hover: hover) and (prefers-reduced-motion: no-preference){.bs-hover--grayscale:hover,
	.bs-hover--grayscale:focus-within{filter: grayscale(0);}}

.bs-animations .bs-animate.is-visible{opacity: 1;
	transform: none;
	filter: none;}
@media (prefers-reduced-motion: reduce){.bs-animations .bs-animate{opacity: 1;
		transform: none;
		filter: none;
		will-change: auto;
		transition: none;}}

.is-scheme-light{color: rgba(255, 255, 255, .9);}
.is-scheme-light :is(h1, h2, h3, h4, h5, h6, .bs-title__text, .bs-icon-box__title, .bs-icon-box__title a){color: #fff;}
.is-scheme-light a:not(.wp-block-button__link):not(.bs-btn){color: #fff;}
.is-scheme-dark{color: var(--bs-text);}
.is-scheme-dark :is(h1, h2, h3, h4, h5, h6){color: var(--bs-heading);}
.bs-section{position: relative;
	display: flex;
	flex-direction: column;
	justify-content: center;
	min-height: var(--bs-sec-min, 0);
	padding-top: var(--bs-sec-pd);
	padding-bottom: var(--bs-sec-pd);
	isolation: isolate;
	overflow: hidden;}
.bs-section--valign-top{justify-content: flex-start;}
.bs-section--valign-bottom{justify-content: flex-end;}
@media (max-width: 849px){.bs-section{padding-top: var(--bs-sec-pt);
		padding-bottom: var(--bs-sec-pt);}}
@media (max-width: 549px){.bs-section{padding-top: var(--bs-sec-pm);
		padding-bottom: var(--bs-sec-pm);}}
.bs-section__bg,
.bs-section__overlay{position: absolute;
	inset: 0;
	z-index: -1;
	pointer-events: none;}
.bs-section__bg{background-repeat: no-repeat;}
.has-fixed-bg .bs-section__bg{background-attachment: fixed;}
@supports (-webkit-touch-callout: none){.has-fixed-bg .bs-section__bg{background-attachment: scroll;}}
.bs-section__inner{position: relative;
	width: 100%;
	max-width: calc(var(--bs-container, 1200px) + 30px);
	margin: 0 auto;
	padding-left: 15px;
	padding-right: 15px;}
.bs-section--narrow .bs-section__inner{max-width: 830px;}
.bs-section--full .bs-section__inner{max-width: none;}
.bs-section__inner > :last-child{margin-bottom: 0;}
.bs-section .bs-section .bs-section__inner{padding-left: 0;
	padding-right: 0;}
.bs-full-width > .bs-section,
.bs-content > .bs-section.alignfull{margin-top: 0;
	margin-bottom: 0;}
.bs-has-transparent-header .bs-full-width > .bs-section:first-child,
.bs-has-transparent-header .bs-content > .bs-section.alignfull:first-child{padding-top: calc(var(--bs-sec-pd) + var(--bs-main-h) + var(--bs-top-h));}
@media (max-width: 849px){.bs-has-transparent-header .bs-full-width > .bs-section:first-child,
	.bs-has-transparent-header .bs-content > .bs-section.alignfull:first-child{padding-top: calc(var(--bs-sec-pt) + var(--bs-mobile-h));}}
.bs-row{--bs-row-gap: 30px;
	display: grid;
	grid-template-columns: repeat(12, minmax(0, 1fr));
	gap: var(--bs-row-gap);
	margin-bottom: 1.5em;}
.bs-row--gap-none{--bs-row-gap: 0px;}
.bs-row--gap-small{--bs-row-gap: 15px;}
.bs-row--gap-large{--bs-row-gap: 50px;}
.bs-row--valign-top{align-items: start;}
.bs-row--valign-center{align-items: center;}
.bs-row--valign-bottom{align-items: end;}
.bs-row--justify-center{justify-content: center;}
.bs-row--justify-end{justify-content: end;}
.bs-row > *{min-width: 0;
	margin-top: 0 !important;
	margin-bottom: 0;}
.bs-column{display: flex;
	flex-direction: column;
	grid-column: span var(--bs-span-d, 6);}
.bs-column--valign-center{justify-content: center;}
.bs-column--valign-bottom{justify-content: flex-end;}
.bs-column > *{margin-top: 0;}
.bs-column > :last-child{margin-bottom: 0;}
@media (max-width: 849px){.bs-row{--bs-row-gap: 24px;}}
@media (max-width: 849px){.bs-row--gap-large{--bs-row-gap: 32px;}}
@media (max-width: 849px){.bs-row--gap-small{--bs-row-gap: 12px;}}
@media (max-width: 849px){.bs-row--gap-none{--bs-row-gap: 0px;}}
@media (max-width: 849px){.bs-column{grid-column: span var(--bs-span-t, 6);}}
@media (max-width: 549px){.bs-row{--bs-row-gap: 20px;}}
@media (max-width: 549px){.bs-column{grid-column: span var(--bs-span-m, 12);}}
@media (max-width: 549px){.bs-row--reverse-mobile > .bs-column{order: 1;}}
@media (max-width: 549px){.bs-row--reverse-mobile > .bs-column:first-child{order: 2;}}

.bs-banner{position: relative;
	display: flex;
	height: var(--bs-banner-hd);
	overflow: hidden;
	border-radius: var(--bs-banner-radius, 0);
	isolation: isolate;}
@media (max-width: 849px){.bs-banner{height: var(--bs-banner-ht);}}
@media (max-width: 549px){.bs-banner{height: var(--bs-banner-hm);}}
.bs-banner__bg,
.bs-banner__overlay,
.bs-banner__link{position: absolute;
	inset: 0;}
.bs-banner__bg{z-index: -2;
	background: var(--bs-light, #eee);}
.bs-banner__picture{display: contents;}
.bs-banner__img{width: 100%;
	height: 100%;
	object-fit: cover;
	transition: transform .8s ease;}
.bs-banner__overlay{z-index: -1;
	transition: opacity .4s ease;}
.bs-banner--hover-zoom:hover .bs-banner__img{transform: scale(1.06);}
.bs-banner--hover-glow:hover .bs-banner__overlay{opacity: .1 !important;}
.bs-banner__link{z-index: 1;}
.bs-banner__content{display: flex;
	width: 100%;
	padding: clamp(20px, 5vw, 60px);
	pointer-events: none;}
.bs-banner__box{position: relative;
	z-index: 2;
	width: var(--bs-banner-width, 70%);
	max-width: 100%;}
.bs-banner__box a,
.bs-banner__box button,
.bs-banner__box input{pointer-events: auto;}
.bs-banner__box > :last-child{margin-bottom: 0;}
.bs-banner--x-left .bs-banner__content{justify-content: flex-start;}
.bs-banner--x-center .bs-banner__content{justify-content: center;}
.bs-banner--x-right .bs-banner__content{justify-content: flex-end;}
.bs-banner--y-top .bs-banner__content{align-items: flex-start;}
.bs-banner--y-middle .bs-banner__content{align-items: center;}
.bs-banner--y-bottom .bs-banner__content{align-items: flex-end;}

.bs-slider{--bs-slides: var(--bs-slides-d, 1);
	position: relative;}
@media (max-width: 849px){.bs-slider{--bs-slides: var(--bs-slides-t, 1);}}
@media (max-width: 549px){.bs-slider{--bs-slides: var(--bs-slides-m, 1);}}
.bs-slider__track{display: grid;
	grid-auto-flow: column;
	grid-auto-columns: calc((100% - (var(--bs-slides) - 1) * var(--bs-slide-gap, 0px)) / var(--bs-slides));
	gap: var(--bs-slide-gap, 0px);
	margin: 0 !important;
	padding: 0 !important;
	overflow-x: auto;
	overscroll-behavior-x: contain;
	scroll-snap-type: x mandatory;
	scrollbar-width: none;
	list-style: none;}
.bs-slider__track::-webkit-scrollbar{display: none;}
.bs-slider__track > *{min-width: 0;
	margin: 0 !important;
	scroll-snap-align: start;}
.bs-slider__arrow{position: absolute;
	top: 50%;
	z-index: 5;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 44px;
	height: 44px;
	padding: 0;
	background: rgba(255, 255, 255, .92);
	color: var(--bs-heading, #111);
	border: 0;
	border-radius: 50%;
	box-shadow: 0 4px 14px rgba(0, 0, 0, .15);
	transform: translateY(-50%);
	cursor: pointer;
	opacity: 0;
	transition: opacity .25s ease, background-color .2s ease, color .2s ease;}
.bs-slider:hover .bs-slider__arrow,
.bs-slider__arrow:focus-visible{opacity: 1;}
@media (hover: none){.bs-slider__arrow{opacity: 1;}}
.bs-slider__arrow:hover{background: var(--bs-primary, #0a4d8c);
	color: #fff;}
.bs-slider__arrow:disabled{opacity: 0 !important;
	pointer-events: none;}
@media (max-width: 549px){.bs-slider--no-arrows-m .bs-slider__arrow{display: none;}}
.bs-slider__arrow--prev{left: 12px;}
.bs-slider__arrow--next{right: 12px;}
.bs-slider--arrows-square .bs-slider__arrow{border-radius: 4px;}
.bs-slider--arrows-minimal .bs-slider__arrow{background: none;
	color: #fff;
	box-shadow: none;
	filter: drop-shadow(0 1px 3px rgba(0, 0, 0, .5));}
.bs-slider--cards .bs-slider__arrow--prev{left: -8px;}
.bs-slider--cards .bs-slider__arrow--next{right: -8px;}
.bs-slider__dots{display: flex;
	flex-wrap: wrap;
	justify-content: center;
	gap: 8px;
	margin-top: 16px;}
.bs-slider__dot{width: 10px;
	height: 10px;
	padding: 0;
	background: var(--bs-border, #ddd);
	border: 0;
	border-radius: 999px;
	cursor: pointer;
	transition: width .25s ease, background-color .25s ease;}
.bs-slider__dot.is-active{width: 26px;
	background: var(--bs-primary, #0a4d8c);}

.bs-icon-box{display: flex;
	flex-direction: column;
	gap: 16px;
	height: 100%;}
.bs-icon-box--align-center{align-items: center;
	text-align: center;}
.bs-icon-box--left{flex-direction: row;
	align-items: flex-start;
	text-align: left;}
.bs-icon-box__icon{display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	color: var(--bs-ib-color, var(--bs-primary));
	transition: transform .3s ease, background-color .3s ease, color .3s ease;}
.bs-icon-box--icon-circle .bs-icon-box__icon,
.bs-icon-box--icon-square .bs-icon-box__icon,
.bs-icon-box--icon-outline .bs-icon-box__icon{width: calc(var(--bs-ib-size, 32px) * 2);
	height: calc(var(--bs-ib-size, 32px) * 2);}
.bs-icon-box--icon-circle .bs-icon-box__icon{background: var(--bs-ib-bg, color-mix(in srgb, var(--bs-primary) 12%, transparent));
	border-radius: 50%;}
.bs-icon-box--icon-square .bs-icon-box__icon{background: var(--bs-ib-bg, color-mix(in srgb, var(--bs-primary) 12%, transparent));
	border-radius: 14px;}
.bs-icon-box--icon-outline .bs-icon-box__icon{border: 2px solid currentColor;
	border-radius: 50%;}
.bs-icon-box:hover .bs-icon-box__icon{transform: translateY(-4px);}
.bs-icon-box__img{max-width: calc(var(--bs-ib-size, 32px) * 2);
	height: auto;}
.bs-icon-box--icon-circle .bs-icon-box__img,
.bs-icon-box--icon-outline .bs-icon-box__img{border-radius: 50%;}
.bs-icon-box__body{min-width: 0;}
.bs-icon-box__title{margin: 0 0 .4em;
	font-size: 1.2em;}
.bs-icon-box__title a{color: inherit;}
.bs-icon-box__text{opacity: .88;}
.bs-icon-box__text > :last-child,
.bs-icon-box__body > :last-child{margin-bottom: 0;}
.bs-icon-box--box-card,
.bs-icon-box--box-bordered{padding: 30px 24px;
	border-radius: 14px;
	transition: transform .3s ease, box-shadow .3s ease;}
.bs-icon-box--box-card{background: #fff;
	box-shadow: 0 6px 24px rgba(15, 23, 42, .08);}
.bs-icon-box--box-card:hover{transform: translateY(-6px);
	box-shadow: 0 18px 40px rgba(15, 23, 42, .14);}
.bs-icon-box--box-bordered{border: 1px solid var(--bs-border, #e5e7eb);}
.bs-icon-box--box-bordered:hover{border-color: var(--bs-primary);}
.bs-title{margin-bottom: 36px;}
.bs-title--align-center{text-align: center;}
.bs-title--align-right{text-align: right;}
.bs-title__subtitle{margin: 0 0 .4em;
	color: var(--bs-secondary);
	font-size: .85em;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: .12em;}
.bs-title__row{display: flex;
	align-items: center;
	gap: 16px;}
.bs-title--align-center .bs-title__row{justify-content: center;}
.bs-title--align-right .bs-title__row{justify-content: flex-end;}
.bs-title__text{position: relative;
	margin: 0;
	color: var(--bs-title-color, var(--bs-heading));
	font-size: var(--bs-title-size, var(--bs-h2));}
.bs-title--bottom-line .bs-title__text{padding-bottom: 14px;}
.bs-title--bottom-line .bs-title__text::after{content: "";
	position: absolute;
	left: 0;
	bottom: 0;
	width: 56px;
	height: 3px;
	background: var(--bs-title-line, var(--bs-primary));
	border-radius: 3px;}
.bs-title--bottom-line.bs-title--align-center .bs-title__text::after{left: 50%;
	transform: translateX(-50%);}
.bs-title--bottom-line.bs-title--align-right .bs-title__text::after{left: auto;
	right: 0;}
.bs-title--center-line .bs-title__row::before,
.bs-title--center-line .bs-title__row::after{content: "";
	flex: 1;
	height: 1px;
	background: var(--bs-title-line, var(--bs-border));}
.bs-title--center-line.bs-title--align-left .bs-title__row::before,
.bs-title--center-line.bs-title--align-right .bs-title__row::after{display: none;}
.bs-title--left-bar .bs-title__text{padding-left: 14px;
	border-left: 4px solid var(--bs-title-line, var(--bs-primary));}
.bs-title--underline-full .bs-title__row{padding-bottom: 10px;
	border-bottom: 2px solid var(--bs-title-line, var(--bs-border));}
.bs-title__link{display: inline-flex;
	align-items: center;
	gap: 4px;
	margin-left: auto;
	font-size: .9em;
	font-weight: 600;
	white-space: nowrap;}
.bs-title--align-center .bs-title__link{margin-left: 0;}

.bs-tabs{margin-bottom: 1.5em;}
.bs-tabs__nav{display: flex;
	flex-wrap: wrap;
	gap: 4px;
	margin-bottom: 24px;}
.bs-tabs--align-center > .bs-tabs__nav{justify-content: center;}
.bs-tabs__tab{padding: 10px 18px;
	background: none;
	color: var(--bs-text);
	border: 0;
	font: inherit;
	font-weight: 600;
	cursor: pointer;
	transition: color .2s ease, background-color .2s ease, border-color .2s ease;}
.bs-tabs--underline > .bs-tabs__nav{border-bottom: 1px solid var(--bs-border);}
.bs-tabs--underline .bs-tabs__tab{margin-bottom: -1px;
	border-bottom: 2px solid transparent;}
.bs-tabs--underline .bs-tabs__tab.is-active,
.bs-tabs--underline .bs-tabs__tab:hover{color: var(--bs-primary);
	border-bottom-color: var(--bs-primary);}
.bs-tabs--pills .bs-tabs__tab{border-radius: 999px;}
.bs-tabs--pills .bs-tabs__tab.is-active{background: var(--bs-primary);
	color: #fff;}
.bs-tabs--boxed > .bs-tabs__nav{gap: 0;
	margin-bottom: 0;}
.bs-tabs--boxed .bs-tabs__tab{background: var(--bs-light);
	border: 1px solid var(--bs-border);
	border-bottom: 0;}
.bs-tabs--boxed .bs-tabs__tab + .bs-tabs__tab{border-left: 0;}
.bs-tabs--boxed .bs-tabs__tab.is-active{background: #fff;
	color: var(--bs-primary);}
.bs-tabs--boxed > .bs-tabs__panels{padding: 24px;
	border: 1px solid var(--bs-border);}
@media (min-width: 850px){.bs-tabs--vertical{display: grid;
		grid-template-columns: 240px minmax(0, 1fr);
		gap: 30px;}}
@media (min-width: 850px){.bs-tabs--vertical > .bs-tabs__nav{flex-direction: column;
		margin: 0;}}
.bs-tabs--vertical .bs-tabs__tab{text-align: left;
	border-left: 3px solid transparent;
	background: var(--bs-light);}
.bs-tabs--vertical .bs-tabs__tab.is-active{color: var(--bs-primary);
	border-left-color: var(--bs-primary);}
.bs-tabs.is-ready .bs-tab:not(.is-active){display: none;}
.bs-tab > :last-child{margin-bottom: 0;}

.bs-accordion{margin-bottom: 1.5em;}
.bs-accordion__item{border: 1px solid var(--bs-border);
	background: #fff;}
.bs-accordion--bordered .bs-accordion__item + .bs-accordion__item{border-top: 0;}
.bs-accordion--bordered .bs-accordion__item:first-child{border-radius: 10px 10px 0 0;}
.bs-accordion--bordered .bs-accordion__item:last-child{border-radius: 0 0 10px 10px;}
.bs-accordion--separated .bs-accordion__item{margin-bottom: 12px;
	border-radius: 10px;
	box-shadow: 0 2px 10px rgba(15, 23, 42, .05);}
.bs-accordion--minimal .bs-accordion__item{background: none;
	border-width: 0 0 1px;}
.bs-accordion__title{display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16px;
	padding: 16px 20px;
	color: var(--bs-heading);
	font-weight: 600;
	list-style: none;
	cursor: pointer;}
.bs-accordion--minimal .bs-accordion__title{padding-left: 0;
	padding-right: 0;}
.bs-accordion__title::-webkit-details-marker{display: none;}
.bs-accordion__title .bs-icon{transition: transform .25s ease;}
.bs-accordion__item[open] > .bs-accordion__title{color: var(--bs-primary);}
.bs-accordion__item[open] > .bs-accordion__title .bs-icon{transform: rotate(180deg);}
.bs-accordion__content{padding: 0 20px 18px;}
.bs-accordion--minimal .bs-accordion__content{padding-left: 0;
	padding-right: 0;}
.bs-accordion__content > :last-child{margin-bottom: 0;}

.bs-block-grid,
.bs-products-block ul.products.bs-products-grid{display: grid;
	grid-template-columns: repeat(var(--bs-cols-d, 3), minmax(0, 1fr));
	gap: 30px;}
