.bs-btn--fx-shine::after{content: ""; position: absolute; top: 0; left: -75%; z-index: 1; width: 50%; height: 100%; background: linear-gradient(100deg, transparent, rgba(255, 255, 255, .45), transparent); transform: skewX(-20deg); pointer-events: none;}
